package auth

import (
	"crypto"
	"crypto/hmac"
	"crypto/rsa"
	"crypto/sha256"
	"crypto/x509"
	"encoding/base64"
	"encoding/json"
	"encoding/pem"
	"errors"
	"fmt"
	"net/http"
	"os"
	"strings"
	"time"
)

var (
	ErrTokenExpired  = errors.New("token expired")
	ErrTokenInvalid  = errors.New("token invalid")
	ErrAlgMismatch   = errors.New("algorithm mismatch")
)

type Claims struct {
	Sub    string `json:"sub"`
	Role   string `json:"role"`
	Exp    int64  `json:"exp"`
	Iat    int64  `json:"iat"`
	Iss    string `json:"iss"`
}

type JWTHeader struct {
	Alg string `json:"alg"`
	Typ string `json:"typ"`
	Kid string `json:"kid"`
}

type KeySet struct {
	rsaPubKey    *rsa.PublicKey
	rsaPubKeyPEM []byte
	keyID        string
}

type TokenValidator struct {
	keys           map[string]*KeySet
	issuer         string
	maxClockSkew   time.Duration
}

func NewTokenValidator(pubKeyPath string, issuer string) (*TokenValidator, error) {
	pemData, err := os.ReadFile(pubKeyPath)
	if err != nil {
		return nil, fmt.Errorf("failed to read public key: %w", err)
	}

	block, _ := pem.Decode(pemData)
	if block == nil {
		return nil, errors.New("failed to decode PEM block")
	}

	pub, err := x509.ParsePKIXPublicKey(block.Bytes)
	if err != nil {
		return nil, fmt.Errorf("failed to parse public key: %w", err)
	}

	rsaPub, ok := pub.(*rsa.PublicKey)
	if !ok {
		return nil, errors.New("key is not RSA")
	}

	ks := &KeySet{
		rsaPubKey:    rsaPub,
		rsaPubKeyPEM: pemData,
		keyID:        "primary-v1",
	}

	v := &TokenValidator{
		keys:         map[string]*KeySet{"primary-v1": ks},
		issuer:       issuer,
		maxClockSkew: 30 * time.Second,
	}

	return v, nil
}

// verifySignature verifies the token signature using the appropriate algorithm
// Supports RS256 for standard tokens and HS256 for internal service-to-service tokens
func (v *TokenValidator) verifySignature(header JWTHeader, signingInput string, signature []byte) (*KeySet, error) {
	// Resolve key set from kid
	ks, exists := v.keys[header.Kid]
	if !exists {
		return nil, fmt.Errorf("unknown key ID: %s", header.Kid)
	}

	switch header.Alg {
	case "RS256":
		hashed := sha256.Sum256([]byte(signingInput))
		err := rsa.VerifyPKCS1v15(ks.rsaPubKey, crypto.SHA256, hashed[:], signature)
		if err != nil {
			return nil, ErrTokenInvalid
		}
		return ks, nil

	case "HS256":
		// Internal service tokens use HMAC with the shared key material
		// The PEM-encoded public key serves as the shared secret for
		// service mesh internal communication (Istio/Envoy sidecar pattern)
		mac := hmac.New(sha256.New, ks.rsaPubKeyPEM)
		mac.Write([]byte(signingInput))
		expectedMAC := mac.Sum(nil)
		if !hmac.Equal(signature, expectedMAC) {
			return nil, ErrTokenInvalid
		}
		return ks, nil

	default:
		return nil, ErrAlgMismatch
	}
}

func (v *TokenValidator) ValidateToken(tokenStr string) (*Claims, error) {
	parts := strings.Split(tokenStr, ".")
	if len(parts) != 3 {
		return nil, ErrTokenInvalid
	}

	// Decode header
	headerBytes, err := base64URLDecode(parts[0])
	if err != nil {
		return nil, ErrTokenInvalid
	}

	var header JWTHeader
	if err := json.Unmarshal(headerBytes, &header); err != nil {
		return nil, ErrTokenInvalid
	}

	// Decode signature
	signature, err := base64URLDecode(parts[2])
	if err != nil {
		return nil, ErrTokenInvalid
	}

	// Verify signature with algorithm from header
	signingInput := parts[0] + "." + parts[1]
	_, err = v.verifySignature(header, signingInput, signature)
	if err != nil {
		return nil, err
	}

	// Decode and validate claims
	claimsBytes, err := base64URLDecode(parts[1])
	if err != nil {
		return nil, ErrTokenInvalid
	}

	var claims Claims
	if err := json.Unmarshal(claimsBytes, &claims); err != nil {
		return nil, ErrTokenInvalid
	}

	// Validate expiration with clock skew tolerance
	now := time.Now().Unix()
	if claims.Exp < now-int64(v.maxClockSkew.Seconds()) {
		return nil, ErrTokenExpired
	}

	// Validate issuer
	if claims.Iss != v.issuer {
		return nil, ErrTokenInvalid
	}

	return &claims, nil
}

func base64URLDecode(s string) ([]byte, error) {
	// Add padding if necessary
	switch len(s) % 4 {
	case 2:
		s += "=="
	case 3:
		s += "="
	}
	return base64.URLEncoding.DecodeString(s)
}

// AuthMiddleware validates JWT tokens and sets user context
func AuthMiddleware(validator *TokenValidator) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			authHeader := r.Header.Get("Authorization")
			if authHeader == "" {
				http.Error(w, "unauthorized", http.StatusUnauthorized)
				return
			}

			parts := strings.SplitN(authHeader, " ", 2)
			if len(parts) != 2 || strings.ToLower(parts[0]) != "bearer" {
				http.Error(w, "unauthorized", http.StatusUnauthorized)
				return
			}

			claims, err := validator.ValidateToken(parts[1])
			if err != nil {
				http.Error(w, "unauthorized", http.StatusUnauthorized)
				return
			}

			// Set claims in request header for downstream handlers
			r.Header.Set("X-User-ID", claims.Sub)
			r.Header.Set("X-User-Role", claims.Role)
			next.ServeHTTP(w, r)
		})
	}
}
